#include <iostream>
#include <vector>

int sum_even(const std::vector<int>& values) {
    int total = 0;
    for (std::size_t index = 0; index < values.size(); index += 1) {
        if (values[index] % 2 == 0) {
            total += values[index];
        }
    }
    return total; // TODO: use std::accumulate
}

int main() {
    const std::vector<int> values = { 3, 4, 6, 7 };
    std::cout << sum_even(values) << "\n";
    return 0;
}
